import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.BXm-Zw-h.js";const k=JSON.parse('{"title":"Slides & Present","description":"","frontmatter":{},"headers":[],"relativePath":"slides.md","filePath":"slides.md","lastUpdated":null}'),n={name:"slides.md"};function o(l,e,d,r,h,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="Slides-and-Present" tabindex="-1">Slides &amp; Present <a class="header-anchor" href="#Slides-and-Present" aria-label="Permalink to &quot;Slides &amp; Present {#Slides-and-Present}&quot;">​</a></h1><p>Any notebook is also a <strong>slide deck</strong>. The same cells you edit group into slides by their headings — no separate authoring mode, no second copy of the content. Present them live in the browser, or export a typeset PDF deck.</p><h2 id="Present-mode-—-Present" tabindex="-1">Present mode — 📽 Present <a class="header-anchor" href="#Present-mode-—-Present" aria-label="Permalink to &quot;Present mode — 📽 Present {#Present-mode-—-Present}&quot;">​</a></h2><p><strong>☰ → 📽 Present</strong> (or <strong>⌘⇧P</strong>) enters full-screen presentation. The notebook&#39;s cells are segmented into slides and shown one at a time.</p><p>Because the deck <em>is</em> the notebook, your figures, tables, and <code>@bind</code> controls are all live on the slide — a slider still drives its chart mid-presentation.</p><p>In the deck: <code>←</code> / <code>→</code> move, <code>Home</code> / <code>End</code> jump to the ends, <code>c</code> toggles code, <code>f</code> toggles fullscreen, and <code>Esc</code> exits back to the editor.</p><h3 id="The-presenter-window" tabindex="-1">The presenter window <a class="header-anchor" href="#The-presenter-window" aria-label="Permalink to &quot;The presenter window {#The-presenter-window}&quot;">​</a></h3><p>Press <code>s</code> (or the 🪞 button, or <em>Open presenter window</em> in the palette) for a second window showing the current and next slide, a timer, and the <strong>speaker notes</strong> from your <code>notes</code> cells. That window is the only place notes are visible. The two stay in step as you advance.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/present-slide.png" alt=""></p><h2 id="How-cells-become-slides" tabindex="-1">How cells become slides <a class="header-anchor" href="#How-cells-become-slides" aria-label="Permalink to &quot;How cells become slides {#How-cells-become-slides}&quot;">​</a></h2><p>Segmentation follows a small set of boundary rules:</p><ol><li><p>A <strong>markdown heading</strong> at or above the slide level (default <code>##</code> / H2) starts a new slide.</p></li><li><p>A cell tagged <strong><code>slide</code></strong> forces a new slide, regardless of headings.</p></li><li><p><strong>PDF only.</strong> A <strong>thematic break</strong> (<code>---</code> on its own line) <em>inside</em> a markdown cell splits it mid-cell into separate slides. The live deck keeps the cell whole, because it moves the real cell onto the stage so charts and <code>@bind</code> controls stay live, and a cell cannot be cut in half. Split the cell yourself to get the same break in both.</p></li><li><p>A cell tagged <strong><code>notes</code></strong> attaches to the current slide as <strong>speaker notes</strong> (never shown in the slide body).</p></li><li><p>Cells before the first boundary form the leading <strong>title slide</strong>.</p></li><li><p><code>collapsed</code> cells are omitted (matching the article/report export).</p></li></ol><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=title</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reactive Notebooks</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">### a five-minute tour</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=idea</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">## The core idea            ← starts slide 2 (H2 heading)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Change a value; only the downstream cells recompute.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% code id=demo slide      ← \`slide\` tag forces slide 3, even without a heading</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@bind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Slider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:line</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">./</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=sp notes          ← speaker notes for slide 3, not shown on it</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Remember to drag the slider here.</span></span></code></pre></div><p>Set the <strong>slide level</strong> (the heading depth that starts a slide, 1 through 6, default 2 for <code>##</code>), the <strong>transition</strong>, and the <strong>aspect ratio</strong> (16:9 or 4:3) per notebook in <strong>☰ → ⚙ Settings → This notebook</strong> (see <a href="/KaimonSlate.jl/dev/settings#This-notebook">Configuration</a>). These pin to the notebook and travel in its <code>.jl</code>.</p><p>The live deck follows the editor theme. A PDF deck takes its theme from the export dialog.</p><h2 id="Export-a-PDF-deck" tabindex="-1">Export a PDF deck <a class="header-anchor" href="#Export-a-PDF-deck" aria-label="Permalink to &quot;Export a PDF deck {#Export-a-PDF-deck}&quot;">​</a></h2><p><strong>☰ → ⬆ Export…</strong>, format <strong>PDF</strong>, layout <strong>🎞 Slides — presentation deck</strong>. This renders a typeset landscape deck <strong>server-side via Typst</strong> — one slide per page, 16:9 (or 4:3), auto-fit:</p><ul><li><p><strong>Code listings are hidden by default</strong> on slides, since a deck usually shows results rather than source. Choosing any non-hidden <strong>Code listings</strong> size brings them back.</p></li><li><p><strong>Vector figures</strong> — CairoMakie embeds as PDF, ECharts as SVG (light+dark captured), so a slide stays crisp on a projector.</p></li><li><p><strong>Speaker notes</strong> — tick <strong>Append speaker-notes pages to the deck</strong> to follow the deck with a notes appendix (one page per slide that has <code>notes</code> cells).</p></li></ul><p>The route is <code>GET /api/&lt;id&gt;/export.pdf?layout=slides</code>. <code>?theme=</code> sets the deck palette (as-is, light or dark, as in the dialog), <code>?notes=1</code> appends the speaker-notes pages, <code>?code=</code> sizes or hides listings, and <code>?columns=</code> is ignored for decks. See <a href="./export">Export</a> for the shared PDF options and the editable Typst project (<code>export.typ</code>).</p><h2 id="Zen-mode" tabindex="-1">Zen mode <a class="header-anchor" href="#Zen-mode" aria-label="Permalink to &quot;Zen mode {#Zen-mode}&quot;">​</a></h2><p><strong>☰ → 🧘 Zen mode</strong> is the other full-page reading view. It hides code and chrome on the same scrollable page, leaving prose and output. <code>Esc</code> returns to the editor.</p><p>Present is the slide deck; Zen is the document.</p><div class="tip custom-block"><p class="custom-block-title">One source, three artifacts</p><p>The same notebook is a live document, a full-screen presentation, and a typeset PDF deck. Add a few <code>##</code> headings and it&#39;s already a deck — refine with <code>slide</code> / <code>notes</code> tags and the per-notebook settings.</p></div>`,23)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
